int process_unique_identifier(char *line, void *data) {
    Context *ctx = (Context *)data;
    int index = 0;
    Header *header;

    // Convert input line to integer index and trim whitespace
    char *endptr;
    index = strtol(line, &endptr, 10);

    if (endptr == line || *endptr != '\0') {
        return -1; // Invalid number format
    }

    // Search for identifier in context's headers
    for (header = ctx->headers; header != NULL; header = header->next) {
        if (header->index == index) {
            // Index matches, update reference number
            header->ref_num = ctx->message.ref_num;
            return 0;
        }
    }

    // Identifier not found, add new header
    header = (Header *)malloc(sizeof(Header));
    if (!header) {
        return -1; // Memory allocation failure
    }

    header->index = index;
    header->ref_num = ctx->message.ref_num;
    header->next = ctx->headers;
    ctx->headers = header;

    // Mark cache for clearing if necessary
    if (ctx->cache_index != index) {
        ctx->clear_cache = 1;
        ctx->cache_index = index;
    }

    return 0;
}

