    struct {
        int ref_num;
        int index;
        struct Header {
            char *identifier;
            int index;
        } *headers;
    } *context = (void *)data;

    // Convert the line to an integer index
    char *endptr;
    context->index = strtol(line, &endptr, 10);

    if (endptr == line || *endptr != '\0') {
        return -1; // Invalid integer format
    }

    // Trim whitespace from the line
    char *trimmed_line = line;
    while (*trimmed_line == ' ' || *trimmed_line == '\t') {
        trimmed_line++;
    }

    // Check for a valid unique identifier
    if (strlen(trimmed_line) == 0) {
        return -1; // Empty identifier
    }

    // Search for the identifier in headers
    int found = 0;
    for (int i = 0; i < context->ref_num; i++) {
        if (strcmp(context->headers[i].identifier, trimmed_line) == 0) {
            found = 1;
            if (context->headers[i].index != context->index) {
                // Index does not match, mark cache for clearing
                // (Implementation of cache clearing not shown)
            }
            break;
        }
    }

    if (!found) {
        // Add new header if identifier not found
        struct Header new_header;
        new_header.identifier = strdup(trimmed_line);
        new_header.index = context->index;
        // Add new_header to context->headers (implementation depends on context)
        context->ref_num++;
    }

    return 0;
}

int process_unique_identifier(char *line, void *data) {
    Context *ctx = (Context *)data;
    int index = 0;
    int status = -1;

    if (line == NULL || ctx == NULL) {
        return -1;
    }

    // Trim whitespace from the line
    char *trimmed_line = line;
    while (*trimmed_line == ' ' || *trimmed_line == '\t') {
        trimmed_line++;
    }

    // Convert the line to an integer index
    char *endptr;
    index = strtol(trimmed_line, &endptr, 10);

    if (endptr == trimmed_line || *endptr != '\0') {
        return -1;
    }

    Header *header = find_header(ctx->headers, trimmed_line);

    if (header == NULL) {
        header = create_header(trimmed_line, index);
        if (header == NULL) {
            return -1;
        }
        add_header(ctx->headers, header);
    } else if (header->index != index) {
        ctx->clear_cache = 1;
    }

    header->reference_number = ctx->message->reference_number;
    header->index = index;

    status = 0;

    return status;
}

int process_unique_identifier(char *line, void *data) {
    MessageContext *ctx = (MessageContext *)data;
    int index = 0;
    char *endptr = NULL;

    // Convert the input line to an integer index
    index = strtol(line, &endptr, 10);

    // Check if the conversion was successful and the line is a valid integer
    if (endptr == line || *endptr != '\0') {
        return -1;
    }

    // Trim whitespace from the line
    while (isspace((unsigned char)*line)) {
        line++;
    }

    // Search for the identifier in the context's headers
    Header *header = find_header(ctx->headers, line);
    if (header == NULL) {
        // If the header doesn't exist, create a new one
        header = add_header(ctx->headers, line, index);
        if (header == NULL) {
            return -1;
        }
    } else if (header->index != index) {
        // If the index does not match, mark the cache for clearing
        mark_cache_for_clearing(ctx->cache);
    }

    // Update the reference number and index of the header
    header->reference_number = ++ctx->reference_count;
    header->index = index;

    return 0;
}
